script:
const s = game.scenes.getName("Alchemist's Shop");
const before = s.grid.size;
await s.update({ 'grid.size': 23 });
return { scene: s.name, before, after: s.grid.size };

const actors = game.actors.filter(a => a.type === 'character').map(a => ({name: a.name, id: a.id, img: a.img, tokenSrc: a.prototypeToken?.texture?.src, sight: a.prototypeToken?.sight?.enabled, link: a.prototypeToken?.actorLink}));
const users = game.users.map(u => ({name: u.name, id: u.id, role: u.role, isGM: u.isGM, charName: u.character?.name ?? null}));
const s = canvas.scene;
return {
  characterActors: actors,
  totalActors: game.actors.size,
  users,
  activeScene: s ? {
    name: s.name, id: s.id,
    grid: s.grid.size, gridType: s.grid.type,
    dims: [s.width, s.height],
    tokenVision: s.tokenVision,
    globalLight: s.environment?.globalLight?.enabled,
    darkness: s.environment?.darknessLevel,
    wallCount: s.walls.size,
    lightCount: s.lights.size,
    tokenCount: s.tokens.size,
    tokens: s.tokens.map(t => ({name: t.name, actorId: t.actorId, x: t.x, y: t.y, sight: t.sight?.enabled}))
  } : null,
  allScenes: game.scenes.map(sc => ({name: sc.name, active: sc.active, walls: sc.walls.size, grid: sc.grid.size}))
};

const s = game.scenes.get('Fj56R7rfpxzITCPy');
return {
  scene: s.name,
  walls: s.walls.map(w => ({id: w.id, c: w.c, move: w.move, sight: w.sight, light: w.light, sound: w.sound, door: w.door, ds: w.ds, _srcKeys: Object.keys(w._source)})),
  lights: s.lights.map(l => ({x: l.x, y: l.y, dim: l.config?.dim, bright: l.config?.bright})),
  env: {darkness: s.environment?.darknessLevel, globalLight: s.environment?.globalLight, tokenVision: s.tokenVision}
};

const MAP = [
  {actor: 'Pipfuhk',    user: 'Pipfuhk',    img: 'assets/tokens/grant-gang/pipfuhk.webp',    hp: 8,  ac: 12},
  {actor: 'Nimbee-Ray', user: 'Nimbee-Ray', img: 'assets/tokens/grant-gang/nimbee-ray.webp', hp: 8,  ac: 12},
  {actor: 'Bargh',      user: 'Bargh',      img: 'assets/tokens/grant-gang/bargh.webp',      hp: 15, ac: 12},
];
const out = [];
for (const m of MAP) {
  const a = game.actors.getName(m.actor);
  const u = game.users.getName(m.user);
  if (!a) { out.push({actor: m.actor, error: 'actor not found'}); continue; }

  // Verify the art exists before pointing at it — a bad path fails silently as a broken tile.
  const probe = await fetch(foundry.utils.getRoute(m.img), {method: 'HEAD'});
  if (!probe.ok) { out.push({actor: m.actor, error: `art missing (${probe.status}) ${m.img}`}); continue; }

  await a.update({
    img: m.img,
    'prototypeToken.texture.src': m.img,
    'prototypeToken.name': m.actor,
    'prototypeToken.actorLink': true,
    'prototypeToken.disposition': 1,
    'prototypeToken.displayName': 30,
    'prototypeToken.displayBars': 40,
    'prototypeToken.sight.enabled': true,
    ...(u ? {[`ownership.${u.id}`]: 3} : {}),
  });
  if (u) await u.update({character: a.id});

  const fresh = game.actors.get(a.id);
  out.push({
    actor: fresh.name,
    img: fresh.img,
    tokenSrc: fresh.prototypeToken.texture.src,
    sight: fresh.prototypeToken.sight.enabled,
    disposition: fresh.prototypeToken.disposition,
    ownerLevel: u ? fresh.ownership[u.id] : null,
    userBound: u ? game.users.get(u.id).character?.name ?? null : 'NO USER',
  });
}
return out;

const s = game.scenes.get('Fj56R7rfpxzITCPy');
const d = canvas.scene?.id === s.id ? canvas.dimensions : null;
return {
  onCanvas: canvas.scene?.name,
  sceneW: s.width, sceneH: s.height, padding: s.padding, grid: s.grid.size,
  dimensions: d ? {
    width: d.width, height: d.height,
    sceneRect: {x: d.sceneRect.x, y: d.sceneRect.y, w: d.sceneRect.width, h: d.sceneRect.height},
    sceneX: d.sceneX, sceneY: d.sceneY
  } : 'scene not rendered on canvas',
  wallBBox: (() => {
    const xs = [], ys = [];
    s.walls.forEach(w => { xs.push(w.c[0], w.c[2]); ys.push(w.c[1], w.c[3]); });
    return {xMin: Math.min(...xs), xMax: Math.max(...xs), yMin: Math.min(...ys), yMax: Math.max(...ys)};
  })()
};

const s = game.scenes.get('Fj56R7rfpxzITCPy');
const G = s.grid.size;

// Door is the gap in the east wall at x=1047, y 1909-1932. Put them in the shop
// proper (east of that wall) so walking through the door is the actual test.
const spots = [
  ['Pipfuhk',    1081, 1886],
  ['Nimbee-Ray', 1081, 1932],
  ['Bargh',      1104, 1909],
];

const rect = {x: 253, y: 506, w: 963, h: 1967};
const docs = [];
for (const [name, rx, ry] of spots) {
  const a = game.actors.getName(name);
  if (!a) throw new Error(`no actor ${name}`);
  const snapped = canvas.grid.getSnappedPoint({x: rx, y: ry}, {mode: CONST.GRID_SNAPPING_MODES.TOP_LEFT_VERTEX});
  const x = Math.min(Math.max(snapped.x, rect.x), rect.x + rect.w - G);
  const y = Math.min(Math.max(snapped.y, rect.y), rect.y + rect.h - G);
  const td = await a.getTokenDocument({x, y});
  docs.push(td.toObject());
}

const created = await s.createEmbeddedDocuments('Token', docs);
await s.activate();

// Readback from the persisted scene, correlated by actorId — not from the create return.
const fresh = game.scenes.get(s.id);
return {
  activeScene: game.scenes.active?.name,
  createdCount: created.length,
  tokens: fresh.tokens.map(t => ({
    name: t.name, actor: t.actor?.name, x: t.x, y: t.y,
    img: t.texture.src, sight: t.sight.enabled, sightRange: t.sight.range,
    disposition: t.disposition, link: t.actorLink
  }))
};

const s = canvas.scene;
const tok = s.tokens.find(t => t.name === 'Bargh');
const origin = {x: tok.x + s.grid.size/2, y: tok.y + s.grid.size/2};

const poly = CONFIG.Canvas.polygonBackends.sight.create(origin, {type: 'sight', hasLimitedRadius: false});

// Probe points: through the open door vs behind solid wall segments.
const probes = [
  ['inside room, straight line through open door', 1000, 1920],
  ['inside room, deep NW corner (behind solid wall)', 780, 1650],
  ['inside room, mid-north (behind solid wall)',      930, 1700],
  ['outside room, open floor east of token',         1150, 1909],
  ['outside room, north of room past wall',           900, 1500],
];
const door = s.walls.find(w => w.door === 1);
return {
  from: {token: tok.name, origin},
  doorState: {c: door.c, door: door.door, ds: door.ds, open: door.ds === 1},
  visibility: probes.map(([label, x, y]) => ({label, x, y, visible: poly.contains(x, y)})),
  env: {darkness: s.environment.darknessLevel, globalLight: s.environment.globalLight.enabled, tokenVision: s.tokenVision},
  note: `wall count ${s.walls.size}, light count ${s.lights.size}`
};

const s = canvas.scene;
const tok = s.tokens.find(t => t.name === 'Bargh');
const origin = {x: tok.x + s.grid.size/2, y: tok.y + s.grid.size/2};
const door = s.walls.find(w => w.door === 1);
const originalDS = door.ds;

const probes = [
  ['inside room, in line with the door', 1000, 1920],
  ['inside room, deep NW corner',         780, 1650],
  ['far south, clear floor (~600px away)',1115, 2400],
  ['far north, clear floor (~900px away)',1115, 1000],
];
const sample = () => {
  const poly = CONFIG.Canvas.polygonBackends.sight.create(origin, {type: 'sight'});
  return Object.fromEntries(probes.map(([l, x, y]) => [l, poly.contains(x, y)]));
};

const closed = sample();
await door.update({ds: 1});               // open
const opened = sample();
await door.update({ds: originalDS});      // restore exactly what it was

return {
  origin,
  doorRestoredTo: s.walls.get(door.id).ds,
  originalWas: originalDS === 1 ? 'OPEN' : 'CLOSED',
  withDoorClosed: closed,
  withDoorOpen: opened,
  sightRange: tok.sight.range,
  gridUnits: `${s.grid.distance}${s.grid.units} per ${s.grid.size}px square`,
};

const s = canvas.scene;
return {
  version: game.version,
  behaviorTypes: Object.keys(CONFIG.RegionBehavior?.dataModels ?? {}),
  adjustDarknessSchema: (() => {
    const M = CONFIG.RegionBehavior?.dataModels?.adjustDarknessLevel;
    if (!M) return 'not present';
    const f = [];
    M.schema.apply(function(){ f.push({name: this.fieldPath, type: this.constructor.name, choices: this.choices, initial: this.initial}); });
    return f;
  })(),
  darknessModes: foundry.data?.regionBehaviors?.AdjustDarknessLevelRegionBehaviorType?.MODES ?? 'unknown',
  sceneEnv: {
    darknessLevel: s.environment.darknessLevel,
    globalLight: s.environment.globalLight,
    base: s.environment.base,
    cycle: s.environment.cycle
  },
  background: s.background?.src ?? s._source.background?.src,
  existingRegions: s.regions?.size ?? 'no regions collection'
};

const s = canvas.scene;

// The shop interior, traced from the existing walls: rectangle with a notch cut
// out of the top-left. Global light is capped at darkness<=0.5 so it switches
// OFF inside the region (which forces darkness to 1) and stays on outdoors.
const INTERIOR = [811,1616, 1047,1616, 1047,2018, 730,2018, 730,1783, 811,1783];

await s.update({
  'environment.darknessLevel': 0,
  'environment.globalLight.enabled': true,
  'environment.globalLight.bright': true,
  'environment.globalLight.darkness.min': 0,
  'environment.globalLight.darkness.max': 0.5,
});

// Remove any previous attempt so re-running is idempotent.
const stale = s.regions.filter(r => r.name === 'Shop Interior').map(r => r.id);
if (stale.length) await s.deleteEmbeddedDocuments('Region', stale);

const [region] = await s.createEmbeddedDocuments('Region', [{
  name: 'Shop Interior',
  color: '#8844ff',
  shapes: [{type: 'polygon', points: INTERIOR, hole: false}],
  behaviors: [{type: 'adjustDarknessLevel', system: {mode: 0, modifier: 1}}],
}]);

const fresh = s.regions.get(region.id);
const b = fresh.behaviors.contents[0];
return {
  region: {
    name: fresh.name,
    shapes: fresh.shapes.map(sh => ({type: sh.type, pointCount: sh.points?.length})),
    behavior: {type: b?.type, mode: b?.system?.mode, modifier: b?.system?.modifier, disabled: b?.disabled},
  },
  env: {
    darknessLevel: s.environment.darknessLevel,
    globalLight: {
      enabled: s.environment.globalLight.enabled,
      bright: s.environment.globalLight.bright,
      darknessRange: [s.environment.globalLight.darkness.min, s.environment.globalLight.darkness.max],
    },
  },
  lightsInsideShop: s.lights.filter(l => l.x > 700 && l.x < 1060 && l.y > 1600 && l.y < 2030).length,
  totalLights: s.lights.size,
};

const s = canvas.scene;
const region = s.regions.getName('Shop Interior');
const probes = [
  ['inside shop — main floor',      950, 1900],
  ['inside shop — upper arm',       950, 1700],
  ['inside notch (should be OUT)',  770, 1700],
  ['outdoors — street west',        500, 1900],
  ['outdoors — north of shop',      950, 1200],
];
const api = {
  getDarknessLevel: typeof canvas.effects?.getDarknessLevel,
  darknessSources: canvas.effects?.darknessSources?.size ?? 'n/a',
  regionTestPoint: typeof region.testPoint,
};
return {
  api,
  probes: probes.map(([label, x, y]) => {
    let inRegion = null, darkness = null;
    try { inRegion = region.testPoint({x, y, elevation: 0}); } catch (e) { inRegion = 'err: ' + e.message; }
    try { darkness = canvas.effects.getDarknessLevel({x, y}); } catch (e) { darkness = 'err: ' + e.message; }
    return {label, x, y, inRegion, darkness};
  }),
  sceneDarkness: s.environment.darknessLevel,
  globalLightActive: canvas.environment?.globalLightSource?.active ?? 'unknown',
};

const s = canvas.scene;
const region = s.regions.getName('Shop Interior');
const b = region.behaviors.contents[0];

const before = {
  darknessSources: canvas.effects.darknessSources.size,
  regionObject: !!region.object,
  behaviorActive: b.active,
  behaviorDisabled: b.disabled,
  regionElevation: {bottom: region.elevation?.bottom, top: region.elevation?.top},
  regionVisibility: region.visibility,
};

canvas.perception.update({
  initializeDarknessSources: true,
  initializeLighting: true,
  initializeVision: true,
  refreshLighting: true,
  refreshVision: true,
});
await new Promise(r => setTimeout(r, 600));

const probe = (x, y) => canvas.effects.getDarknessLevel({x, y});
return {
  before,
  after: {
    darknessSources: canvas.effects.darknessSources.size,
    insideShop: probe(950, 1900),
    insideUpperArm: probe(950, 1700),
    outdoorsWest: probe(500, 1900),
    outdoorsNorth: probe(950, 1200),
  },
  behaviorSystem: {mode: b.system.mode, modifier: b.system.modifier},
  hasShapes: region.shapes.length,
  polygonTree: !!region.polygonTree,
};

const s = canvas.scene;
const region = s.regions.getName('Shop Interior');
const b = region.behaviors.contents[0];
const dlm = canvas.effects.illumination.darknessLevelMeshes;
return {
  behavior: {uuid: b.uuid, type: b.type, active: b.active, viewed: b.viewed, disabled: b.disabled, mode: b.system.mode, modifier: b.system.modifier},
  regionDoc: {viewed: region.viewed, visibility: region.visibility, objectVisible: region.object?.visible, elevation: {b: region.elevation.bottom, t: region.elevation.top}},
  darknessLevelMeshes: {
    count: dlm.children.length,
    names: dlm.children.map(c => c.name),
    uniforms: dlm.children.map(c => ({name: c.name, darknessLevel: c.shader?.uniforms?.darknessLevel, mode: c.shader?.mode, modifier: c.shader?.modifier})),
  },
  globalMeshes: canvas.visibility.vision.light.global.meshes.children.map(c => c.name),
  regionsLayerPlaceables: canvas.regions?.placeables?.map(p => p.document.name),
  globalLightSource: {active: canvas.environment.globalLightSource.active, darknessRange: canvas.environment.globalLightSource.data?.darkness},
};

const s = canvas.scene;
const probe = (x, y) => canvas.effects.getDarknessLevel({x, y, elevation: 0});
const lit = (x, y) => canvas.effects.testInsideLight({x, y, elevation: 0}, {});
const pts = [
  ['inside shop — main floor',        950, 1900],
  ['inside shop — upper arm',         950, 1700],
  ['inside shop — dark corner',       760, 1990],
  ['the notch (outside walls)',       770, 1700],
  ['outdoors — street west',          500, 1900],
  ['outdoors — north of shop',        950, 1200],
  ['outdoors — far south',            600, 2400],
];
return {
  results: pts.map(([label, x, y]) => {
    let inLight = null;
    try { inLight = lit(x, y); } catch (e) { inLight = 'n/a'; }
    return {label, darkness: probe(x, y), inLampLight: inLight};
  }),
  sceneDarknessDefault: canvas.environment.darknessLevel,
  globalLight: {active: canvas.environment.globalLightSource.active, range: canvas.environment.globalLightSource.data?.darkness},
};

const out = {};
for (const n of ['Pipfuhk','Nimbee-Ray','Bargh']) {
  const a = game.actors.getName(n);
  const pt = a.prototypeToken;
  out[n] = {
    race: a.system.details?.race?.name ?? a.system.details?.race ?? null,
    senses: a.system.attributes?.senses,
    sight: {enabled: pt.sight.enabled, range: pt.sight.range, mode: pt.sight.visionMode,
            attenuation: pt.sight.attenuation, brightness: pt.sight.brightness, saturation: pt.sight.saturation},
    detectionModes: pt.detectionModes?.map(d => ({id: d.id, range: d.range, enabled: d.enabled})),
  };
}
return {
  pcs: out,
  visionModes: Object.keys(CONFIG.Canvas.visionModes),
  globalLightSchema: Object.keys(canvas.scene.environment.globalLight),
  sceneUnits: `${canvas.scene.grid.distance}${canvas.scene.grid.units}/square`,
};

const out = {};
for (const n of ['Pipfuhk','Nimbee-Ray','Bargh']) {
  const a = game.actors.getName(n);
  const pt = a.prototypeToken.toObject();
  out[n] = {
    race: a.system.details?.race?.name ?? a.system.details?.race ?? null,
    senses: a.system.attributes?.senses,
    sight: pt.sight,
    detectionModes: pt.detectionModes,
  };
}
return {
  pcs: out,
  visionModes: Object.keys(CONFIG.Canvas.visionModes),
  detectionModeIds: Object.keys(CONFIG.Canvas.detectionModes),
  globalLightFields: canvas.scene.environment.globalLight,
  sceneUnits: `${canvas.scene.grid.distance}${canvas.scene.grid.units}/square, ${canvas.scene.grid.size}px`,
};

const s = canvas.scene;
return {
  scene: s.name,
  darknessLevel_source: s._source.environment.darknessLevel,
  darknessLevel_live: canvas.environment.darknessLevel,
  cycle: s.environment.cycle,
  globalLight: s._source.environment.globalLight,
  globalLightSourceActive: canvas.environment.globalLightSource.active,
  lights: s.lights.map(l => ({
    x: l.x, y: l.y, hidden: l.hidden,
    dim: l.config.dim, bright: l.config.bright,
    darknessWindow: [l.config.darkness.min, l.config.darkness.max],
    active: canvas.lighting.get(l.id)?.lightSource?.active,
  })),
  regionDarkness: canvas.effects.getDarknessLevel({x: 950, y: 1900, elevation: 0}),
  outdoorDarkness: canvas.effects.getDarknessLevel({x: 500, y: 1900, elevation: 0}),
};

const s = canvas.scene;
const original = s._source.environment.darknessLevel;

const sample = (label) => ({
  label,
  sceneDarkness: canvas.environment.darknessLevel,
  globalLightActive: canvas.environment.globalLightSource.active,
  outdoorDarkness: canvas.effects.getDarknessLevel({x: 500, y: 1900, elevation: 0}),
  indoorDarkness: canvas.effects.getDarknessLevel({x: 950, y: 1900, elevation: 0}),
  outdoorLit: canvas.effects.testInsideLight({x: 500, y: 1900, elevation: 0}, {}),
  indoorLit: canvas.effects.testInsideLight({x: 950, y: 1900, elevation: 0}, {}),
  lampsActive: s.lights.filter(l => canvas.lighting.get(l.id)?.lightSource?.active).length,
});

const before = sample(`darkness ${original} (as found)`);
await s.update({'environment.darknessLevel': 1.0}, {animateDarkness: 0});
await new Promise(r => setTimeout(r, 400));
const night = sample('darkness 1.0 (night button)');
await s.update({'environment.darknessLevel': original}, {animateDarkness: 0});
await new Promise(r => setTimeout(r, 400));
const restored = sample(`restored to ${original}`);

return {
  before, night, restored,
  darknessLock: s.environment.darknessLock,
  cycle: s.environment.cycle,
  globalLightWindow: [s.environment.globalLight.darkness.min, s.environment.globalLight.darkness.max],
};

const s = game.scenes.getName('The Common Room');
return {
  id: s.id, name: s.name, active: s.active,
  grid: {size: s.grid.size, distance: s.grid.distance, units: s.grid.units, type: s.grid.type},
  dims: {width: s.width, height: s.height, padding: s.padding},
  background: s._source.background?.src ?? s.background?.src,
  squaresAcross: (s.width / s.grid.size).toFixed(1),
  squaresDown: (s.height / s.grid.size).toFixed(1),
  contents: {walls: s.walls.size, lights: s.lights.size, tokens: s.tokens.size, tiles: s.tiles.size, regions: s.regions.size},
  GRID_MIN_SIZE: CONST.GRID_MIN_SIZE,
};

const s = game.scenes.getName('The Common Room');
const before = {size: s.grid.size, distance: s.grid.distance};
await s.update({'grid.size': 20, 'grid.distance': 5});
const f = game.scenes.get(s.id);
return {
  before,
  after: {size: f._source.grid.size, distance: f._source.grid.distance, units: f._source.grid.units},
  squares: {across: +(f.width / f.grid.size).toFixed(1), down: +(f.height / f.grid.size).toFixed(1)},
  mapFeet: {wide: Math.round(f.width / f.grid.size * f.grid.distance), tall: Math.round(f.height / f.grid.size * f.grid.distance)},
  subdivision: `each old ${before.size}px square is now ${before.size/20}x${before.size/20} = ${(before.size/20)**2} squares`,
  atGridMin: f.grid.size === CONST.GRID_MIN_SIZE,
};

const out = [];
for (const s of game.scenes) {
  const walls = s.walls.contents;
  if (!walls.length) { out.push({name: s.name, walls: 0}); continue; }
  // endpoint multiset -> how many are exactly shared
  const key = (x,y) => `${x},${y}`;
  const counts = new Map();
  for (const w of walls) {
    for (const [x,y] of [[w.c[0],w.c[1]],[w.c[2],w.c[3]]]) {
      const k = key(x,y); counts.set(k, (counts.get(k)||0)+1);
    }
  }
  let deg1 = 0;
  for (const [,n] of counts) if (n === 1) deg1++;
  // nearest-neighbour distances among degree-1 endpoints
  const pts = [];
  for (const [k,n] of counts) if (n === 1) { const [x,y]=k.split(',').map(Number); pts.push([x,y]); }
  const nn = [];
  for (let i=0;i<pts.length;i++){
    let best = Infinity;
    for (let j=0;j<pts.length;j++){ if(i===j) continue;
      const dx=pts[i][0]-pts[j][0], dy=pts[i][1]-pts[j][1]; const d=dx*dx+dy*dy;
      if (d<best) best=d; }
    if (best<Infinity) nn.push(Math.round(Math.sqrt(best)));
  }
  nn.sort((a,b)=>a-b);
  const doors = walls.filter(w=>w.door!==0).length;
  const classes = {};
  for (const w of walls) { const c = `move${w.move}/sight${w.sight}${w.door?`/door${w.door}`:''}`; classes[c]=(classes[c]||0)+1; }
  out.push({
    name: s.name, walls: walls.length, doors,
    gridType: s.grid.type, gridSize: s.grid.size, gridDistance: s.grid.distance,
    distinctEndpoints: counts.size, danglingEndpoints: deg1,
    nnDistancesAmongDangling: nn.slice(0, 12),
    classes,
    nonIntegerCoords: walls.filter(w=>w.c.some(v=>!Number.isInteger(v))).length,
    zeroLength: walls.filter(w=>w.c[0]===w.c[2]&&w.c[1]===w.c[3]).length,
    oneWay: walls.filter(w=>w.dir!==0).length,
    maxCoord: Math.max(...walls.flatMap(w=>w.c.map(Math.abs)))
  });
}
return out;

const out = {};
for (const s of game.scenes) {
  if (!s.walls.size) continue;
  out[s.name] = {
    gridSize: s.grid.size,
    walls: s.walls.map(w => ({_id: w.id, c: w.c, door: w.door, ds: w.ds, sight: w.sight,
                              move: w.move, light: w.light, sound: w.sound, dir: w.dir}))
  };
}
return JSON.stringify(out);

const m = game.modules.get("pentaryn-walls");
const cfg = game.settings.get("core", "moduleConfiguration");
return {
  visible: !!m,
  title: m?.title,
  version: m?.version,
  active: m?.active,
  configuredOn: cfg?.["pentaryn-walls"] ?? null,
  world: game.world.id,
  foundry: game.version,
  otherPentaryn: Object.keys(cfg ?? {}).filter(k => k.startsWith("pentaryn"))
};

return {
  activeUsers: game.users.filter(u => u.active).map(u => ({name: u.name, isGM: u.isGM, self: u.id === game.user.id})),
  scene: canvas?.scene?.name ?? null
};

