// Collect ItemGrant uuids from an item's advancement up to a level
function grantUuids(itemDoc, level) {
  const adv = itemDoc.toObject().system.advancement ?? {};
  const uuids = [];
  for (const a of Object.values(adv)) {
    if (a.type !== "ItemGrant") continue;
    if ((a.level ?? 1) > level) continue;
    for (const it of (a.configuration?.items ?? [])) {
      const u = typeof it === "string" ? it : it.uuid;
      if (u && !it.optional) uuids.push(u);
    }
  }
  return uuids;
}

