const cache = {};
async function ls(dir) {
  if (cache[dir]) return cache[dir];
  try {
    const r = await foundry.applications.apps.FilePicker.implementation.browse("data", dir);
    return cache[dir] = r.files;
  } catch { return cache[dir] = []; }
}
async function resolve(prefs) {
