  const already = a.items.find(i => i.type === "feat" && i.name.toLowerCase().startsWith(featName.toLowerCase()));
  let addedFeat = already?.name ?? null;
  if (!already) {
    const e = fIdx.find(x => x.name.toLowerCase() === featName.toLowerCase())
      ?? fIdx.find(x => x.name.toLowerCase().startsWith(featName.toLowerCase()));
