// Pull the real features back out of the class advancement they came from
async function restore(actorName, className, featureName) {
  const a = game.actors.getName(actorName);
  const clsE = clsIdx.find(e => e.name === className && e.type === "class");
  const clsDoc = await CLS.getDocument(clsE._id);
  const adv = clsDoc.toObject().system.advancement ?? {};
  let uuid = null;
  for (const entry of Object.values(adv)) {
    if (entry.type !== "ItemGrant") continue;
    for (const it of (entry.configuration?.items ?? [])) {
      const u = typeof it === "string" ? it : it.uuid;
      const doc = u ? await fromUuid(u) : null;
      if (doc?.name === featureName) uuid = u;
    }
  }
  if (!uuid) return { actor: actorName, error: `could not locate ${featureName} in ${className} advancement` };
  const already = a.items.find(i => i.name === featureName);
  if (!already) {
    const d = (await fromUuid(uuid)).toObject(); delete d._id;
    await a.createEmbeddedDocuments("Item", [d]);
  }
  // remove the authored replacement
  const authored = a.items.filter(i => i.flags?.["space-journey"]?.authored && i.flags["space-journey"].replaces === featureName);
  if (authored.length) await a.deleteEmbeddedDocuments("Item", authored.map(i => i.id));
  return { actor: actorName, restored: featureName, removed: authored.map(i => i.name) };
}

