  if (kill.length) await a.deleteEmbeddedDocuments("Item", kill.map(i => i.id));
  // mark every remaining leveled 'prepared'-mode spell as actually prepared
  const upd = [...seen.values()]
    .filter(s => s.system.level > 0 && s.system.preparation?.mode === "prepared" && !s.system.preparation?.prepared)
    .map(s => ({ _id: s.id, "system.preparation.prepared": true }));
  if (upd.length) await a.updateEmbeddedDocuments("Item", upd);
