async function give(actorName, pack, idx, names) {
  const a = game.actors.getName(actorName);
  const add = [], missing = [];
  for (const nm of names) {
    if (a.items.find(i => i.name.toLowerCase() === nm.toLowerCase())) continue;
    const e = idx.find(x => x.name.toLowerCase() === nm.toLowerCase());
    if (!e) { missing.push(nm); continue; }
    const d = (await pack.getDocument(e._id)).toObject(); delete d._id;
    add.push(d);
  }
  if (add.length) await a.createEmbeddedDocuments("Item", add);
  return { actor: actorName, added: add.map(d => d.name), missing };
}

