const report = [];
for (const n of NAMES) {
  const a = game.actors.getName(n);
  // Gather Trait grants from every spec-owned source item
  const sources = a.items.filter(i => ["class","subclass","race","background"].includes(i.type));
  const grants = new Set();
  for (const it of sources) {
    for (const adv of Object.values(it.toObject().system.advancement ?? {})) {
      if (adv.type !== "Trait" || (adv.level ?? 1) > 5) continue;
      if (adv.configuration?.mode === "mastery") continue;
      for (const g of (adv.configuration?.grants ?? [])) grants.add(g);
    }
  }
  const upd = {};
  const weap = new Set(a.system.traits?.weaponProf?.value ?? []);
  const armr = new Set(a.system.traits?.armorProf?.value ?? []);
  const langs = new Set(a.system.traits?.languages?.value ?? []);
  const applied = [];
  for (const g of grants) {
    const [kind, key] = g.split(":");
    if (kind === "saves")     { upd[`system.abilities.${key}.proficient`] = 1; applied.push(g); }
    else if (kind === "skills") { upd[`system.skills.${key}.value`] = 1; applied.push(g); }
    else if (kind === "weapon") { weap.add(key); applied.push(g); }
    else if (kind === "armor")  { armr.add(key); applied.push(g); }
    else if (kind === "languages") { langs.add(key); applied.push(g); }
  }
  upd["system.traits.weaponProf.value"] = [...weap];
  upd["system.traits.armorProf.value"] = [...armr];
  upd["system.traits.languages.value"] = [...langs];
  // pinned skill picks
  for (const s of SKILLS[n].prof) upd[`system.skills.${s}.value`] = Math.max(1, upd[`system.skills.${s}.value`] ?? 0);
  for (const s of SKILLS[n].exp)  upd[`system.skills.${s}.value`] = 2;
  await a.update(upd);

  const f = game.actors.getName(n);
  const w = f.items.find(i => i.type === "weapon" && i.system.magicalBonus);
  const atk = w?.system.activities?.contents?.find(x => x.type === "attack");
  report.push({
    name: n,
    grantsApplied: applied.sort(),
    saves: Object.entries(f.system.abilities).filter(([, v]) => v.proficient).map(([k]) => k),
    skills: Object.entries(f.system.skills).filter(([, v]) => v.value > 0).map(([k, v]) => v.value === 2 ? `${k}*` : k),
    weaponProf: f.system.traits.weaponProf.value,
    armorProf: f.system.traits.armorProf.value,
    magicWeapon: w ? `${w.name} ${atk?.labels?.toHit ?? "?"}` : "—",
    ac: f.system.attributes.ac.value
  });
}
return report;

