const scenePacks = [
  game.packs.get("pentaryn-seafoot-maps.scenes"),
  game.packs.find(p => p.metadata.packageName === "mad-endlesswiz" && p.documentName === "Scene"),
  game.packs.find(p => p.metadata.packageName === "mad-endlesswiz2" && p.documentName === "Scene"),
  game.packs.find(p => p.metadata.packageName === "eledryll-spiders-tear-opera-house" && p.documentName === "Scene"),
].filter(Boolean);
for (const p of scenePacks) await p.getIndex();

function resolve(name) {
  const norm = s => s.toLowerCase().replace(/[’']/g, "'").trim();
  for (const p of scenePacks) {
    const exact = p.index.find(e => norm(e.name) === norm(name));
    if (exact) return { pack: p, entry: exact, how: "exact" };
  }
  for (const p of scenePacks) {
    const loose = p.index.find(e => norm(e.name).includes(norm(name)) || norm(name).includes(norm(e.name)));
    if (loose) return { pack: p, entry: loose, how: "fuzzy" };
  }
  return null;
}

