function walk(f, depth) {
  const children = folders.filter(x => x.folder?.id === f.id);
  return {
    id: f.id, name: f.name, depth,
    scenes: game.scenes.filter(s => s.folder?.id === f.id).map(s => ({id: s.id, name: s.name, nav: s.navigation})),
    children: children.map(c => walk(c, depth+1))
  };
}
return root ? walk(root, 0) : folders.map(f => ({id: f.id, name: f.name, folder: f.folder?.id}));

