for (const spec of specs) {
  const actor = game.actors.getName(spec.actor);
  if (!actor) { results.push({error: "actor not found", actor: spec.actor, scene: spec.scene}); continue; }
  const scene = game.scenes.get(spec.scene);
  if (!scene) { results.push({error: "scene not found", actor: spec.actor, scene: spec.scene}); continue; }
  const cols = Math.min(spec.count, 6);
  const toCreate = [];
  for (let i = 0; i < spec.count; i++) {
    const td = await actor.getTokenDocument({
      x: 300 + (i % cols) * 150,
      y: 300 + Math.floor(i / cols) * 150,
      hidden: !!spec.hidden,
    });
    const obj = td.toObject();
    delete obj._id;
    if (spec.tokenName) obj.name = spec.tokenName;
    toCreate.push(obj);
  }
  try {
    const created = await scene.createEmbeddedDocuments("Token", toCreate);
    results.push({actor: spec.actor, scene: scene.name, requested: spec.count, created: created.length});
  } catch (e) {
    results.push({error: String(e), actor: spec.actor, scene: scene.name});
  }
}
const errors = results.filter(r => r.error);
const totalCreated = results.reduce((s, r) => s + (r.created || 0), 0);
return { totalSpecs: specs.length, totalTokensCreated: totalCreated, errorCount: errors.length, errors };

